pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length == v.length && _tos.length > 0);
        vm.assume(from != address(0) && caddress != address(0));
        // Deploy a simple ERC20-like token that tracks balances
        TestToken token = new TestToken();
        // Setup: give 'from' some tokens and approve caddress to spend
        token.mint(from, 1000);
        vm.prank(from);
        token.approve(address(c), 1000);
        // Record from's balance before transfer
        uint256 balanceBefore = token.balanceOf(from);
        // Drive the call
        c.transfer(from, address(token), _tos, v);
        // Rule: balance of 'from' must remain unchanged (since transferFrom requires approval, which is set)
        uint256 balanceAfter = token.balanceOf(from);
        assertTrue(balanceAfter == balanceBefore, "Balance should not change after transfer via transferFrom");
    }
}

contract TestToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address to, uint256 amount) public { balanceOf[to] += amount; }
    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    function transfer(address to, uint256 amount) public returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

