pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        vm.assume(from != address(0) && caddress != address(0));
        vm.assume(caddress != address(c));
        // We need an actual token contract at caddress that has a transferFrom that returns false.
        // To isolate the property, we deploy a minimal token that always returns false on transferFrom and true on transfer.
        // We'll do this by deploying a small contract inside the test.
        // However, since the test must only interact through c, we can deploy the token externally via create2 and use a known address.
        // Simpler: use vm.etch to pre-deploy a contract with known bytecode.
        // For brevity, we just assume a token exists at caddress that returns false for transferFrom and true for transfer.
        // To avoid complexity, we'll just check that the call doesn't revert for the reference (which always uses transferFrom).
        // Actually, the property we want is that the reference's call selector is transferFrom, so the call's return data's first 4 bytes are different.
        // Since we can't read internal call return data, we must design a simpler rule.
        // Let's use a different approach: deploy a mock that records the selector called.
        // Create a mock contract inside the test.
        MockToken mock = new MockToken();
        caddress = address(mock);
        c.transfer(from, caddress, _tos, v);
        bool calledTransferFrom = mock.calledTransferFrom();
        assertTrue(!calledTransferFrom, "Reference should not call transferFrom directly but transferFrom selector");
    }
}

contract MockToken {
    bool public calledTransferFrom;
    function transferFrom(address, address, uint256) external returns (bool) {
        calledTransferFrom = true;
        return false;
    }
    function transfer(address, uint256) external returns (bool) {
        calledTransferFrom = false; // not transferFrom
        return true;
    }
    fallback() external {}
}

