import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        vm.assume(from != address(0) && caddress != address(0));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0) && v[i] > 0);
        }
        // Deploy a simple ERC20 token at caddress that has balanceOf and transfer/transferFrom
        // We assume caddress is an ERC20 token with these functions
        // Record initial balances of to-addresses
        uint256[] memory initialBalances = new uint256[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.call(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            if (success && data.length == 32) {
                initialBalances[i] = abi.decode(data, (uint256));
            } else {
                // If balanceOf fails, assume 0 balance
                initialBalances[i] = 0;
            }
        }
        // Call the transfer function
        bool success = c.transfer(from, caddress, _tos, v);
        // After call, sum of final balances should equal sum of initial balances for reference
        // For the mutant, the sum increases (since tokens are transferred from from to _tos)
        uint256 sumInitial = 0;
        uint256 sumFinal = 0;
        for (uint i = 0; i < _tos.length; i++) {
            (bool ok, bytes memory data) = caddress.call(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            uint256 finalBalance;
            if (ok && data.length == 32) {
                finalBalance = abi.decode(data, (uint256));
            } else {
                finalBalance = 0;
            }
            sumInitial += initialBalances[i];
            sumFinal += finalBalance;
        }
        assertTrue(sumFinal == sumInitial, "Sum of to-address balances should be unchanged after transferFrom call");
    }
}

