pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint256[] memory amounts) public {
        // Constrain inputs to avoid failing require and excessive assumption rejections
        vm.assume(tos.length > 0);
        vm.assume(tos.length == amounts.length);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        for (uint256 i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
            vm.assume(amounts[i] > 0);
        }

        // Deploy a mock ERC20 token that implements transferFrom and transfer
        // We'll use a simple contract that reverts on transferFrom if not approved
        // But for simplicity, we'll test the call return value
        // We need a token at caddress that returns true for transfer and false for transferFrom
        // Deploy a mock token that has the desired behavior
        MockToken token = new MockToken();
        vm.etCH(address(token), 0); // No ether needed

        // Replace caddress with the mock token address
        caddress = address(token);

        // Now call c.transfer
        bool success = c.transfer(from, caddress, tos, amounts);

        // The property: the call inside transfer should have failed because transferFrom is not approved
        // But the contract doesn't bubble up revert, so we check the token's internal state
        // We can check that the token's balance of 'from' remains unchanged
        // For the reference (using transferFrom), the transfer should fail and balances unchanged
        // For the mutant (using transfer), the transfer should succeed and balances change
        // We cannot distinguish directly in a general way without knowing which version.
        // Instead, we use a trick: the call to caddress returns a boolean that we can check
        // by seeing if the token's state changed. We'll check that the from balance is still 0
        // (since no approval was given). If the mutant uses transfer, the from balance becomes >0
        // But the reference transferFrom would fail and balance stays 0.

        // Actually, we need a rule that the reference always satisfies.
        // The rule: after calling c.transfer, the balance of 'from' in the mock token should be 0
        // because transferFrom fails. The mutant would make it >0.
        uint256 fromBalance = token.balanceOf(from);
        assertTrue(fromBalance == 0, "from balance should be zero since transferFrom fails");
    }
}

// Helper contract to act as a token that returns appropriate values
contract MockToken {
    mapping(address => uint256) public balanceOf;

    function transfer(address to, uint256 amount) public returns (bool) {
        balanceOf[msg.sender] -= amount; // This will underflow if insufficient balance, but we don't care for the test
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        // Will fail because no approval, but we just return false
        return false;
    }
}

